		if isCode(err, maelstrom.KeyDoesNotExist) {
			return nil, false, nil
		}
		return nil, false, fmt.Errorf("read %s: %w", logKey(key), err)
	}
	switch a := v.(type) {
	case nil:
		return nil, true, nil
	case []any:
		return a, true, nil
	default:
		return nil, false, fmt.Errorf("log %s holds %T, not a list", logKey(key), v)
	}
}

