		exists := true
		cur, err := s.kv.ReadInt(ctx, ck)
		if err != nil {
			if !isCode(err, maelstrom.KeyDoesNotExist) {
				return fmt.Errorf("read %s: %w", ck, err)
			}
			exists = false
		}
